-- Disposable fixtures only. No owner data or credentials; all changes roll back.
begin;
create function pg_temp.invest_assert(ok boolean,label text) returns void language plpgsql as $$ begin
 if ok is not true then raise exception 'FAIL: %',label;end if;
 perform set_config('folio.invest_checks',(coalesce(nullif(current_setting('folio.invest_checks',true),''),'0')::int+1)::text,true);
end $$;
create function pg_temp.invest_error(statement text,expected text,label text) returns void language plpgsql as $$ begin
 begin execute statement;exception when others then
  if sqlstate<>expected then raise exception 'FAIL: % expected %, got %: %',label,expected,sqlstate,sqlerrm;end if;
  perform pg_temp.invest_assert(true,label);return;
 end;raise exception 'FAIL: % accepted',label;
end $$;
with u as(insert into auth.users(id,email) values(gen_random_uuid(),'invest-a@example.invalid') returning id) select set_config('folio.invest_a',id::text,true) from u;
with u as(insert into auth.users(id,email) values(gen_random_uuid(),'invest-b@example.invalid') returning id) select set_config('folio.invest_b',id::text,true) from u;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('folio.invest_a'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.invest_a'),'is_anonymous',false)::text,true);
select public.initialize_workspace();
with a as(insert into public.accounts(name,type,opening_balance_paise) values('Synthetic bank','bank',1000000) returning id) select set_config('folio.invest_bank',id::text,true) from a;
select set_config('folio.invest_terms','{"name":"Synthetic NPS","scheme":"nps_tier_1","provider":"Fixture CRA","funding_source":"self","locked_until":null,"account_id":null,"archived":false}',true);
select set_config('folio.invest_request',gen_random_uuid()::text,true);
select set_config('folio.invest_nps',public.save_investment_holding(null,0,current_setting('folio.invest_terms')::jsonb,2000029,folio_private.today()-1,current_setting('folio.invest_request')::uuid)::text,true);
select pg_temp.invest_assert(public.save_investment_holding(null,0,current_setting('folio.invest_terms')::jsonb,2000029,folio_private.today()-1,current_setting('folio.invest_request')::uuid)=current_setting('folio.invest_nps')::uuid,'holding creation retries once');
select pg_temp.invest_assert((select count(*)=1 from public.investment_holdings),'one holding after retry');
select pg_temp.invest_assert((select count(*)=1 from public.investment_entries),'one opening valuation after retry');
select pg_temp.invest_assert((public.workspace_snapshot()->'summary'->>'net_worth_paise')::bigint=3000029,'reported assets enter net worth exactly');
select pg_temp.invest_assert((public.workspace_snapshot()->'summary'->>'assets_paise')::bigint=3000029,'reported assets enter assets');
select pg_temp.invest_assert((public.workspace_snapshot()->'summary'->>'liquid_cash_paise')::bigint=1000000,'investments never increase available cash');
select set_config('folio.invest_epf',public.save_investment_holding(null,0,(current_setting('folio.invest_terms')::jsonb)||'{"name":"Synthetic EPF","scheme":"epf","funding_source":"payroll"}',500000,folio_private.today()-1,gen_random_uuid())::text,true);
select set_config('folio.invest_entry_request',gen_random_uuid()::text,true);
select set_config('folio.invest_entry',public.record_investment_entry(current_setting('folio.invest_nps')::uuid,1,null,'self',10029,folio_private.today(),'Fixture own contribution',false,current_setting('folio.invest_entry_request')::uuid)::text,true);
select pg_temp.invest_assert(public.record_investment_entry(current_setting('folio.invest_nps')::uuid,1,null,'self',10029,folio_private.today(),'Fixture own contribution',false,current_setting('folio.invest_entry_request')::uuid)=current_setting('folio.invest_entry')::uuid,'contribution retries once');
select pg_temp.invest_assert((select count(*)=0 from public.transactions),'tracking history posts no bank transaction');
select pg_temp.invest_assert((public.investment_portfolio()->0->>'value_paise')::bigint=2000029,'contribution does not invent a new statement balance');
select pg_temp.invest_assert((public.investment_portfolio()->0->>'self_paise')::bigint=10029,'own contribution precision retained');
select pg_temp.invest_assert((public.investment_portfolio()->0->>'fy_self_paise')::bigint=10029,'current financial year own contribution');
select pg_temp.invest_assert((public.investment_portfolio()->0->>'activity_after_valuation')::int=1,'activity after statement marked for review');
select pg_temp.invest_error(format('select public.record_investment_entry(%L::uuid,1,null,''self'',1,folio_private.today(),'''',false,gen_random_uuid())',current_setting('folio.invest_nps')),'40001','stale history form rejected');
select public.record_investment_entry(current_setting('folio.invest_epf')::uuid,1,null,'self',20000,folio_private.today(),'Payroll deduction',false,gen_random_uuid());
select public.record_investment_entry(current_setting('folio.invest_epf')::uuid,2,null,'employer',30000,folio_private.today(),'Employer EPF only',false,gen_random_uuid());
select pg_temp.invest_assert((public.investment_portfolio()->1->>'funding_source')='payroll' and (public.investment_portfolio()->1->>'employer_paise')::bigint=30000,'EPF payroll and employer records separate');
select pg_temp.invest_assert((public.workspace_snapshot()->'summary'->>'income_paise')::bigint=0 and (public.workspace_snapshot()->'summary'->>'expense_paise')::bigint=0,'payroll history does not create salary or expense');
select public.record_investment_entry(current_setting('folio.invest_nps')::uuid,2,current_setting('folio.invest_entry')::uuid,'self',20029,folio_private.today(),'Corrected contribution',false,gen_random_uuid());
select pg_temp.invest_assert((public.investment_portfolio()->0->>'self_paise')::bigint=20029,'history amount can be corrected');
select public.record_investment_entry(current_setting('folio.invest_nps')::uuid,3,current_setting('folio.invest_entry')::uuid,'self',0,folio_private.today(),'',true,gen_random_uuid());
select pg_temp.invest_assert((public.investment_portfolio()->0->>'self_paise')::bigint=0,'history deletion reverses tracked total only');
select public.record_investment_entry(current_setting('folio.invest_nps')::uuid,4,null,'valuation',90000,folio_private.today()-3,'Older statement',false,gen_random_uuid());
select pg_temp.invest_assert((public.investment_portfolio()->0->>'value_paise')::bigint=2000029,'backdated statement does not replace latest value');
select public.record_investment_entry(current_setting('folio.invest_nps')::uuid,5,null,'valuation',2200029,folio_private.today(),'New statement',false,gen_random_uuid());
select pg_temp.invest_assert((public.workspace_snapshot()->'summary'->>'net_worth_paise')::bigint=3700029,'new valuation updates net worth');
select pg_temp.invest_assert((public.workspace_snapshot()->'summary'->>'liquid_cash_paise')::bigint=1000000,'new valuation does not create spendable cash');
select pg_temp.invest_error(format('select public.record_investment_entry(%L::uuid,3,(select id from public.investment_entries where holding_id=%L::uuid and kind=''valuation''),''valuation'',0,folio_private.today(),'''',true,gen_random_uuid())',current_setting('folio.invest_epf'),current_setting('folio.invest_epf')),'P0001','last valuation cannot be removed');
select pg_temp.invest_error('update public.investment_holdings set name=''Forbidden''','42501','direct holding writes denied');
select pg_temp.invest_error('delete from public.investment_entries','42501','direct history deletes denied');
select pg_temp.invest_error(format('select public.record_investment_entry(%L::uuid,6,null,''self'',0,folio_private.today(),'''',false,gen_random_uuid())',current_setting('folio.invest_nps')),'P0001','zero contribution rejected');
select pg_temp.invest_error(format('select public.record_investment_entry(%L::uuid,6,null,''valuation'',-1,folio_private.today(),'''',false,gen_random_uuid())',current_setting('folio.invest_nps')),'P0001','negative valuation rejected');
select pg_temp.invest_error(format('select public.record_investment_entry(%L::uuid,6,null,''valuation'',1,folio_private.today()+1,'''',false,gen_random_uuid())',current_setting('folio.invest_nps')),'P0001','future activity rejected');
select pg_temp.invest_error(format('select public.save_investment_holding(null,0,%L::jsonb,1,folio_private.today(),gen_random_uuid())',current_setting('folio.invest_terms')::jsonb||'{"raw_statement":"forbidden"}'),'P0001','unknown metadata rejected');
select pg_temp.invest_error(format('select public.save_investment_holding(null,0,%L::jsonb,1000000000000,folio_private.today(),gen_random_uuid())',current_setting('folio.invest_terms')),'22003','out-of-range portfolio rolls back');
select pg_temp.invest_assert((select count(*)=2 from public.investment_holdings),'failed aggregate leaves no orphan holding');
with a as(insert into public.accounts(name,type,opening_balance_paise) values('Synthetic investment account','investment',2000000) returning id) select set_config('folio.invest_account',id::text,true) from a;
select set_config('folio.invest_linked_terms',(current_setting('folio.invest_terms')::jsonb||jsonb_build_object('account_id',current_setting('folio.invest_account')))::text,true);
select public.save_investment_holding(current_setting('folio.invest_nps')::uuid,6,current_setting('folio.invest_linked_terms')::jsonb,null,null,gen_random_uuid());
select pg_temp.invest_assert((public.workspace_snapshot()->'summary'->>'net_worth_paise')::bigint=3500000,'linked holding principal not counted twice');
select pg_temp.invest_error(format('select public.save_investment_holding(null,0,%L::jsonb,1,folio_private.today(),gen_random_uuid())',current_setting('folio.invest_linked_terms')),'23505','same investment account cannot be linked twice');
select pg_temp.invest_error(format('update public.accounts set type=''bank'' where id=%L::uuid',current_setting('folio.invest_account')),'P0001','linked account retains investment type');
select pg_temp.invest_error(format('select public.save_investment_holding(null,0,%L::jsonb,1,folio_private.today(),gen_random_uuid())',current_setting('folio.invest_terms')::jsonb||jsonb_build_object('account_id',current_setting('folio.invest_bank'))),'42501','cash account cannot masquerade as linked investment');
select public.save_investment_holding(current_setting('folio.invest_nps')::uuid,7,current_setting('folio.invest_linked_terms')::jsonb||'{"archived":true}',null,null,gen_random_uuid());
select pg_temp.invest_assert((public.workspace_snapshot()->'summary'->>'net_worth_paise')::bigint=3500000,'archiving retains assets');
select pg_temp.invest_error(format('select public.record_investment_entry(%L::uuid,8,null,''valuation'',1,folio_private.today(),'''',false,gen_random_uuid())',current_setting('folio.invest_nps')),'P0001','archived holding must reopen for new history');
-- Backdated history is not mistaken for the current India financial year.
select public.record_investment_entry(current_setting('folio.invest_epf')::uuid,3,null,'self',7500,make_date(extract(year from folio_private.today())::int-case when extract(month from folio_private.today())<4 then 1 else 0 end,4,1)-1,'Previous FY contribution',false,gen_random_uuid());
select pg_temp.invest_assert((public.investment_portfolio()->1->>'fy_self_paise')::bigint=20000 and (public.investment_portfolio()->1->>'self_paise')::bigint=27500,'prior financial year excluded from current FY');
select set_config('folio.invest_zero_value',public.record_investment_entry(current_setting('folio.invest_epf')::uuid,4,null,'valuation',0,folio_private.today(),'Fully withdrawn value',false,gen_random_uuid())::text,true);
select pg_temp.invest_assert((public.investment_portfolio()->1->>'value_paise')::bigint=0,'zero statement valuation accepted');
select public.record_investment_entry(current_setting('folio.invest_epf')::uuid,5,current_setting('folio.invest_zero_value')::uuid,'valuation',0,folio_private.today(),'',true,gen_random_uuid());
select pg_temp.invest_assert((public.investment_portfolio()->1->>'value_paise')::bigint=500000,'removing latest valuation restores previous report');
select public.record_investment_entry(current_setting('folio.invest_epf')::uuid,6,null,'withdrawal',5000,folio_private.today(),'Withdrawal history',false,gen_random_uuid());
select pg_temp.invest_assert((public.investment_portfolio()->1->>'withdrawn_paise')::bigint=5000 and (select count(*)=0 from public.transactions),'withdrawal history is not a cash posting');
select pg_temp.invest_error(format('select public.record_investment_entry(%L::uuid,7,null,''self'',1000000000000,folio_private.today(),'''',false,gen_random_uuid())',current_setting('folio.invest_epf')),'22003','history aggregate range rejected atomically');
select pg_temp.invest_assert((public.investment_portfolio()->1->>'self_paise')::bigint=27500 and (public.investment_portfolio()->1->>'revision')::int=7,'range failure retains history and revision');
select pg_temp.invest_error(format('select public.record_investment_entry(%L::uuid,8,(select id from public.investment_entries where holding_id=%L::uuid limit 1),''valuation'',0,folio_private.today(),'''',true,gen_random_uuid())',current_setting('folio.invest_nps'),current_setting('folio.invest_epf')),'42501','history cannot move between holdings');
select pg_temp.invest_error(format('select public.save_investment_holding(null,0,%L::jsonb,2000030,folio_private.today()-1,%L::uuid)',current_setting('folio.invest_terms'),current_setting('folio.invest_request')),'P0001','request ID cannot be reused for altered values');
select set_config('request.jwt.claim.sub',current_setting('folio.invest_b'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.invest_b'),'is_anonymous',false)::text,true);
select pg_temp.invest_assert((select count(*)=0 from public.investment_holdings) and (select count(*)=0 from public.investment_entries),'another owner cannot read holdings or history');
select pg_temp.invest_error(format('select public.save_investment_holding(%L::uuid,8,%L::jsonb,null,null,gen_random_uuid())',current_setting('folio.invest_nps'),current_setting('folio.invest_terms')),'42501','another owner cannot update holding');
select pg_temp.invest_error(format('select public.record_investment_entry(%L::uuid,8,null,''valuation'',1,folio_private.today(),'''',false,gen_random_uuid())',current_setting('folio.invest_nps')),'42501','another owner cannot add history');
select pg_temp.invest_error(format('select public.save_investment_holding(null,0,%L::jsonb,1,folio_private.today(),gen_random_uuid())',current_setting('folio.invest_linked_terms')),'42501','another owner cannot link the account');
select set_config('request.jwt.claim.sub',current_setting('folio.invest_a'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.invest_a'),'is_anonymous',true)::text,true);
select pg_temp.invest_assert((select count(*)=0 from public.investment_holdings),'anonymous-auth user cannot read investments');
select pg_temp.invest_error('select public.investment_portfolio()','42501','anonymous-auth RPC denied');
set local role anon;
select pg_temp.invest_error('select * from public.investment_entries','42501','signed-out history denied');
select pg_temp.invest_error('select public.investment_portfolio()','42501','signed-out portfolio denied');
select current_setting('folio.invest_checks') as investment_assertions_passed;
rollback;
